-- 406: Original BrillaPrep WASSCE Core Mathematics sprint 1 beta questions, part 4 of 8 (batch wassce-core-math-sprint1-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_406_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_406_guard;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_019' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the area of a triangle with base 12 cm and height 5 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 60 cm²","B. 17 cm²","C. 30 cm²","D. 32.5 cm²"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Area of a triangle = ½ × base × height = ½ × 12 × 5 = 30 cm². (Forgetting the ½ gives the trap answer 60 cm².) Therefore the correct answer is C: 30 cm².' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_019' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_020' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the complement of the angle 35°.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 145°","B. 65°","C. 35°","D. 55°"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Complementary angles add to 90°, so the complement is 90° − 35° = 55°. (145° is the supplement, not the complement.) Therefore the correct answer is D: 55°.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_020' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_021' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the size of each exterior angle of a regular hexagon.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 60°","B. 120°","C. 45°","D. 90°"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The exterior angles of any polygon add to 360°. A regular hexagon has 6 equal exterior angles, so each is 360° ÷ 6 = 60°. (120° is each interior angle.) Therefore the correct answer is A: 60°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_021' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_022' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Taking π = 22/7, find the circumference of a circle of radius 7 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 22 cm","B. 44 cm","C. 154 cm","D. 88 cm"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Circumference = 2πr = 2 × (22/7) × 7 = 2 × 22 = 44 cm. (154 cm² would be the area, not the circumference.) Therefore the correct answer is B: 44 cm.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_022' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_023' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The angles of a triangle are in the ratio 1 : 2 : 3. Find the largest angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 60°","B. 120°","C. 90°","D. 45°"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The angles sum to 180° across 1 + 2 + 3 = 6 parts, so one part is 180° ÷ 6 = 30°. The largest angle is 3 × 30° = 90°, making this a right-angled triangle. Therefore the correct answer is C: 90°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_023' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_406_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_024' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An arc of a circle subtends an angle of 35° at the circumference. Find the angle the same arc subtends at the centre of the circle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 17.5°","B. 35°","C. 55°","D. 70°"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The angle a given arc subtends at the centre is twice the angle it subtends at the circumference: 2 × 35° = 70°. Therefore the correct answer is D: 70°.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_024' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_019', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the area of a triangle with base 12 cm and height 5 cm.', 'multiple_choice', NULL, '["A. 60 cm²","B. 17 cm²","C. 30 cm²","D. 32.5 cm²"]', 'C', 'Area of a triangle = ½ × base × height = ½ × 12 × 5 = 30 cm². (Forgetting the ½ gives the trap answer 60 cm².) Therefore the correct answer is C: 30 cm².', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO1', NULL, NULL, 'board_waec');
