INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_024', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'An arc of a circle subtends an angle of 35° at the circumference. Find the angle the same arc subtends at the centre of the circle.', 'multiple_choice', NULL, '["A. 17.5°","B. 35°","C. 55°","D. 70°"]', 'D', 'The angle a given arc subtends at the centre is twice the angle it subtends at the circumference: 2 × 35° = 70°. Therefore the correct answer is D: 70°.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
